//! Worldgen P24 researcher and administrator experience contract.
//! Produces role-aware, omission-aware workbench cards without moving raw data.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use std::collections::BTreeSet;
