pub const FEATURE_ID:&str="AFA-worldgen-P24-F01";pub const CONTRACT_VERSION:&str="worldgen-local-researcher-admin-experience/1.0";pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.researcher-admin-experience-receipt-1+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct WorkspacePanel4{pub panel_id:String,pub label:String,pub role:String,pub content_digest:ContentHash,pub visible:bool,pub requires_approval:bool,pub local:bool,pub aggregate_only:bool,pub evidence_state:String,pub omission_reason:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct WorkspaceRequest4{pub request_id:String,pub scope:String,pub study_id:String,pub role:String,pub panels:Vec<WorkspacePanel4>,pub required_panel_order:Vec<String>,pub requested_action_order:Vec<String>,pub approved_action_order:Vec<String>,pub policy_allowed:bool,pub protected_closure:bool,pub signed_approval:bool,pub network_available:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub replay_identity:ContentHash,pub adversarial_events:Vec<String>,pub action_budget:u32,pub action_count:u32,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct WorkspaceArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:ContentHash,pub semantic_loss:Vec<String>,pub panel_digests:Vec<ContentHash>,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct ResearchWorkspaceCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub mode:String,pub scale:String,pub request_id:String,pub study_id:String,pub role:String,pub disposition:String,pub panel_order:Vec<String>,pub selected_panel_order:Vec<String>,pub hidden_panel_order:Vec<String>,pub omitted_panel_order:Vec<String>,pub unknown_panel_order:Vec<String>,pub denied_panel_order:Vec<String>,pub negative_panel_order:Vec<String>,pub required_panel_order:Vec<String>,pub action_order:Vec<String>,pub approved_action_order:Vec<String>,pub accessibility_order:Vec<String>,pub audit_order:Vec<String>,pub replay_identity:ContentHash,pub workspace_digest:ContentHash,pub artifact:WorkspaceArtifact4,pub effect_receipts:Vec<String>,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum ResearcherAdminExperienceError{#[error("invalid workspace request: {0}")]Invalid(String),#[error("workspace card failed validation: {0}")]Output(String)}
fn ord(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}fn dig(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn ne(v:&str)->bool{!v.trim().is_empty()}
pub fn manifest(id:&str,version:&str,scale:&str,mode:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":id,"version":version,"owner_crate":"worldgen","consumers":["preclinical researcher","study administrator","accessibility reviewer","provenance auditor"],"behavior":format!("render a role-aware, omission-aware research workspace at {scale} ({mode})"),"value":"makes permitted research state accessible without hiding protected, missing, uncertain, or negative evidence","input_schema":"WorkspaceRequest4@1","output_schema":"ResearchWorkspaceCard7@1","effects":["view:research-workspace","manage:local-capability","block:unsafe-release"],"permissions":["read:authorized-research-summaries"],"determinism":"byte_stable","autonomy_tier":"A0","boundary":PRECLINICAL_BOUNDARY})}
impl ResearchWorkspaceCard7{pub fn validate(&self)->Result<(),ResearcherAdminExperienceError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||!ne(&self.contract_version)||!ne(&self.feature_id)||!ne(&self.mode)||!ne(&self.scale)||!ne(&self.request_id)||!ne(&self.study_id)||!ne(&self.role)||self.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.panel_order.is_empty()||!ord(&self.panel_order)||!ord(&self.selected_panel_order)||!ord(&self.hidden_panel_order)||!ord(&self.omitted_panel_order)||!ord(&self.unknown_panel_order)||!ord(&self.denied_panel_order)||!ord(&self.negative_panel_order)||!ord(&self.required_panel_order)||!ord(&self.action_order)||!ord(&self.approved_action_order)||!ord(&self.accessibility_order)||!ord(&self.audit_order)||!dig(&self.replay_identity)||!dig(&self.workspace_digest)||self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.workspace_digest||self.artifact.boundary!=PRECLINICAL_BOUNDARY||!self.effect_receipts.iter().all(|e|e.starts_with("view:research-workspace:")||e.starts_with("manage:local-capability:")||e=="block:unsafe-release"){return Err(ResearcherAdminExperienceError::Output("workspace identity, ordering, locality, digest, or effect is invalid".into()))}let ids=BTreeSet::from_iter(self.panel_order.iter().cloned());let parts=self.selected_panel_order.iter().chain(&self.hidden_panel_order).chain(&self.omitted_panel_order).chain(&self.unknown_panel_order).chain(&self.denied_panel_order).cloned().collect::<Vec<_>>();if ids.len()!=self.panel_order.len()||parts.len()!=ids.len()||BTreeSet::from_iter(parts)!=ids{return Err(ResearcherAdminExperienceError::Output("panel states do not partition".into()))}Ok(())}pub fn digest(&self)->Result<ContentHash,ResearcherAdminExperienceError>{self.validate()?;let value=serde_json::to_value(self).map_err(|e|ResearcherAdminExperienceError::Output(e.to_string()))?;ContentHash::of_value(&value).map_err(|e|ResearcherAdminExperienceError::Output(e.to_string()))}}
pub fn render(request:&WorkspaceRequest4,id:&str,version:&str,scale:&str,mode:&str)->Result<ResearchWorkspaceCard7,ResearcherAdminExperienceError>{if !ne(&request.request_id)||!ne(&request.scope)||!ne(&request.study_id)||!ne(&request.role)||request.panels.is_empty()||request.required_panel_order.is_empty()||!dig(&request.replay_identity)||request.boundary!=PRECLINICAL_BOUNDARY||!request.raw_data_local||!request.aggregate_only||!ord(&request.required_panel_order)||!ord(&request.requested_action_order)||!ord(&request.approved_action_order)||!ord(&request.adversarial_events){return Err(ResearcherAdminExperienceError::Invalid("workspace identity, required panels, ordering, digest, locality, or boundary is invalid".into()))}let mut rows=request.panels.clone();rows.sort_by(|a,b|a.panel_id.cmp(&b.panel_id));let mut seen=BTreeSet::new();let mut panels=Vec::new();let mut selected=BTreeSet::new();let mut hidden=BTreeSet::new();let mut omitted=BTreeSet::new();let mut unknown=BTreeSet::new();let mut denied=BTreeSet::new();let mut negative=BTreeSet::new();let mut digests=BTreeSet::new();for p in &rows{if !seen.insert(p.panel_id.clone())||!ne(&p.panel_id)||!ne(&p.label)||!ne(&p.role)||!dig(&p.content_digest)||!ne(&p.evidence_state){return Err(ResearcherAdminExperienceError::Invalid("panel identity or digest is invalid".into()))}panels.push(p.panel_id.clone());digests.insert(p.content_digest.clone());if p.evidence_state=="negative"{negative.insert(p.panel_id.clone());}if !p.local||!p.aggregate_only||!ne(&p.omission_reason){omitted.insert(p.panel_id.clone());}else if !p.visible{hidden.insert(p.panel_id.clone());}else if p.role!=request.role||p.requires_approval&&!request.signed_approval{denied.insert(p.panel_id.clone());}else{match p.evidence_state.as_str(){"proven"|"supported"=>{selected.insert(p.panel_id.clone());},"unknown"|"unmeasured"|"contradicted"=>{unknown.insert(p.panel_id.clone());},_=>{unknown.insert(p.panel_id.clone());}}}}let global=!request.policy_allowed||!request.protected_closure||!request.raw_data_local||!request.aggregate_only||!request.network_available||!request.adversarial_events.is_empty()||(mode=="research copilot"&&(request.action_budget==0||request.action_count>request.action_budget));if global{omitted.extend(panels.iter().cloned());selected.clear();hidden.clear();unknown.clear();denied.clear();}let required=BTreeSet::from_iter(request.required_panel_order.iter().cloned());let complete=required.is_subset(&selected);let disposition=if global{"blocked"}else if !request.signed_approval&&mode!="inference"{"approval_required"}else if complete&&unknown.is_empty()&&omitted.is_empty()&&denied.is_empty(){"ready"}else if !selected.is_empty(){"partial"}else{"unknown"};let actions=request.requested_action_order.clone();let approved=request.approved_action_order.clone();let mut accessibility:BTreeSet<String>=BTreeSet::new();accessibility.insert("keyboard-navigation".into());accessibility.insert("screen-reader-labels".into());accessibility.insert("contrast-checked".into());let mut audit:BTreeSet<String>=BTreeSet::new();audit.insert(format!("role:{}",request.role));audit.insert(format!("study:{}",request.study_id));audit.insert(format!("panels:{}",panels.len()));if !omitted.is_empty(){audit.insert("omissions:visible".into());}if !negative.is_empty(){audit.insert("negative-evidence:visible".into());}let mut payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":id,"mode":mode,"scale":scale,"request_id":request.request_id,"study_id":request.study_id,"role":request.role,"disposition":disposition,"panel_order":panels,"selected_panel_order":selected.into_iter().collect::<Vec<_>>(),"hidden_panel_order":hidden.into_iter().collect::<Vec<_>>(),"omitted_panel_order":omitted.into_iter().collect::<Vec<_>>(),"unknown_panel_order":unknown.into_iter().collect::<Vec<_>>(),"denied_panel_order":denied.into_iter().collect::<Vec<_>>(),"negative_panel_order":negative.into_iter().collect::<Vec<_>>(),"required_panel_order":request.required_panel_order,"action_order":actions,"approved_action_order":approved,"accessibility_order":accessibility.into_iter().collect::<Vec<_>>(),"audit_order":audit.into_iter().collect::<Vec<_>>(),"replay_identity":request.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let digest=ContentHash::of_value(&payload).map_err(|e|ResearcherAdminExperienceError::Output(e.to_string()))?;payload["workspace_digest"]=json!(digest);payload["artifact"]=json!({"artifact_id":format!("worldgen-research-workspace:{}",request.request_id),"content_type":CONTENT_TYPE,"content_hash":digest,"semantic_loss":payload["omitted_panel_order"],"panel_digests":digests.into_iter().collect::<Vec<_>>(),"boundary":PRECLINICAL_BOUNDARY});payload["effect_receipts"]=json!(if disposition=="ready"{vec![format!("view:research-workspace:{}",request.request_id),format!("manage:local-capability:{}",request.request_id)]}else{vec!["block:unsafe-release".to_string()]});let out:ResearchWorkspaceCard7=serde_json::from_value(payload).map_err(|e|ResearcherAdminExperienceError::Output(e.to_string()))?;out.validate()?;Ok(out)}
#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn q()->WorkspaceRequest4{WorkspaceRequest4{request_id:"ws:req".into(),scope:"study:local".into(),study_id:"study:1".into(),role:"researcher".into(),panels:vec![WorkspacePanel4{panel_id:"panel:methods".into(),label:"Methods".into(),role:"researcher".into(),content_digest:h("methods"),visible:true,requires_approval:false,local:true,aggregate_only:true,evidence_state:"supported".into(),omission_reason:"none".into()}],required_panel_order:vec!["panel:methods".into()],requested_action_order:vec!["view".into()],approved_action_order:vec!["view".into()],policy_allowed:true,protected_closure:true,signed_approval:true,network_available:true,raw_data_local:true,aggregate_only:true,replay_identity:h("replay"),adversarial_events:vec![],action_budget:2,action_count:1,boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn ready(){assert_eq!(render(&q(),FEATURE_ID,CONTRACT_VERSION,"local single-study","inference").unwrap().disposition,"ready")}#[test]fn omission_is_partial(){let mut x=q();x.panels[0].local=false;assert_eq!(render(&x,FEATURE_ID,CONTRACT_VERSION,"local single-study","inference").unwrap().disposition,"unknown")}#[test]fn policy_blocks(){let mut x=q();x.policy_allowed=false;assert_eq!(render(&x,FEATURE_ID,CONTRACT_VERSION,"local single-study","inference").unwrap().disposition,"blocked")}}
